{
  "rule": "2",
  "edits": [
    {
      "location": "Section 1 — Foundations: What Is a Power System?",
      "original": "The architecture of a power system is therefore not merely a physical infrastructure, but also a complex socio‑technical system that incorporates market mechanisms, regulatory frameworks, and increasingly, sophisticated information‑communication technologies (ICT).",
      "revised": "The architecture of a power system is therefore a complex socio‑technical system that incorporates market mechanisms, regulatory frameworks, and increasingly, sophisticated information‑communication technologies (ICT).",
      "reason": "Negative windup deleted: the positive half alone states the same claim (the physical-infrastructure point is already made earlier in the section)."
    },
    {
      "location": "Section 2.1 — Conventional Generators",
      "original": "Frequency restoration after a 500 MW trip fell from 12 minutes to 4 minutes, so the retune significantly shortens frequency restoration.",
      "revised": "Frequency restoration after a 500 MW trip fell from 12 minutes to 4 minutes.",
      "reason": "Definition doubling: the second half restates through synonym ('significantly shortens') what the figures already prove; deleting it loses nothing checkable."
    },
    {
      "location": "Section 2.1 — Conventional Generators",
      "original": "Operators procured spinning reserve, rather than non-spinning reserve.",
      "revised": "Operators procured spinning reserve.",
      "reason": "Negative tail deleted: 'spinning reserve' already excludes the alternative; the denial adds no new fact."
    },
    {
      "location": "Section 6.1 — Reliability and Resilience",
      "original": "The Texas failure was not a nameplate shortfall of wind; frozen gas wells and unheated thermal auxiliaries accounted for the lost megawatts. Frozen wellheads cut gas supply—thermal units then tripped on auxiliary freeze.",
      "revised": "Frozen gas wells and unheated thermal auxiliaries accounted for the lost megawatts in the Texas failure.",
      "reason": "Negative windup deleted, and the follow-up sentence was a synonym restatement of the same two causes (frozen wells, auxiliary freeze) adding no new checkable fact."
    },
    {
      "location": "Section 6.3 — Market and Regulatory Complexity",
      "original": "Those upgrades are planned on purpose, rather than by accident.",
      "revised": "Those upgrades are planned on purpose.",
      "reason": "Negative tail deleted: 'rather than by accident' is a windup restatement of 'planned'; nothing lost when removed."
    }
  ],
  "untouched_near_misses": [
    "Renewable units are often sited where resources are abundant, not where demand peaks — the contrast carries the checkable claim (geographic mismatch); deleting it breaks the following 'requiring robust transmission networks'.",
    "Inertia still matters for the first few cycles after a trip, full stop. / Islanded operation is the only backup path for those hospitals, end of story. — emphatic tags, not negative windups or doubled definitions; outside this rule."
  ]
}

